generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalHoldingGain ?netCashFlow ?riskPressureScore WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasPortfolioHealth ?ph .

  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain) WHERE {
      ?h a wm:PortfolioHolding ;
         wm:heldByInvestor ?invH ;
         wm:currentValue ?cv ;
         wm:cost ?c .
      ?invH wm:investorId ?investorId .
      BIND (xsd:decimal(?cv) - xsd:decimal(?c) AS ?gain)
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?amt)) AS ?netCashFlow) WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?invC ;
          wm:amount ?amt .
      ?invC wm:investorId ?investorId .
    } GROUP BY ?investorId
  }

  ?ph wm:riskScore ?riskScore ;
      wm:liquidityScore ?liqScore ;
      wm:diversificationScore ?divScore .
  BIND (xsd:decimal(?riskScore) + (100 - xsd:decimal(?liqScore)) + (100 - xsd:decimal(?divScore)) AS ?riskPressureScore)

  FILTER(?totalHoldingGain < 0 && ?netCashFlow < 0 && ?riskPressureScore > 180)
}

